import{_ as t,o as s,c as n,a4 as e}from"./chunks/framework.BBs01uty.js";const g=JSON.parse('{"title":"JVM 入门","description":"","frontmatter":{},"headers":[],"relativePath":"service/java-jvm.md","filePath":"service/java-jvm.md"}'),d={name:"service/java-jvm.md"};function o(r,a,l,p,i,c){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="jvm-入门" tabindex="-1">JVM 入门 <a class="header-anchor" href="#jvm-入门" aria-label="Permalink to &quot;JVM 入门&quot;">​</a></h1><blockquote><p><strong>优先级：P0（面试必考）</strong> — JVM 与并发并称 Java 面试两大护城河，几乎必问。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">背景</p><p>JS 开发者不需要关心 V8 内存细节也能干活；但 Java 面试会把 JVM 内存模型、GC、类加载当基础题问。本文聚焦面试考点，不深入源码。</p></div><h2 id="jvm-是什么" tabindex="-1">JVM 是什么 <a class="header-anchor" href="#jvm-是什么" aria-label="Permalink to &quot;JVM 是什么&quot;">​</a></h2><p>Java 程序运行在 JVM（Java Virtual Machine）上：<code>.java</code> 编译为 <code>.class</code> 字节码，JVM 解释/编译执行。<strong>一次编译，到处运行</strong> 靠的就是 JVM 屏蔽了操作系统差异。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.java --javac--&gt; .class --JVM--&gt; 机器码</span></span></code></pre></div><h2 id="内存分区-必考-画图题" tabindex="-1">内存分区（必考，画图题） <a class="header-anchor" href="#内存分区-必考-画图题" aria-label="Permalink to &quot;内存分区（必考，画图题）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│ 线程共享                              │</span></span>
<span class="line"><span>│  ┌──────────┬──────────┬──────────┐  │</span></span>
<span class="line"><span>│  │  堆 Heap  │ 方法区/元空间 │  直接内存 │  │</span></span>
<span class="line"><span>│  │ (对象实例) │ (类信息/常量) │ (NIO)    │  │</span></span>
<span class="line"><span>│  └──────────┴──────────┴──────────┘  │</span></span>
<span class="line"><span>├─────────────────────────────────────┤</span></span>
<span class="line"><span>│ 线程私有                              │</span></span>
<span class="line"><span>│  ┌──────────┬──────────┬──────────┐  │</span></span>
<span class="line"><span>│  │ 虚拟机栈    │ 本地方法栈 │ 程序计数器 │  │</span></span>
<span class="line"><span>│  │ (方法调用) │ (native) │ (下一条指令)│  │</span></span>
<span class="line"><span>│  └──────────┴──────────┴──────────┘  │</span></span>
<span class="line"><span>└─────────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>区域</th><th>存什么</th><th>线程</th><th>异常</th></tr></thead><tbody><tr><td><strong>堆</strong></td><td>所有对象实例、数组</td><td>共享</td><td><code>OutOfMemoryError: Java heap space</code></td></tr><tr><td><strong>方法区/元空间</strong></td><td>类信息、常量、静态变量（JDK 8+ 用元空间，本地内存）</td><td>共享</td><td><code>OOM: Metaspace</code></td></tr><tr><td><strong>虚拟机栈</strong></td><td>每个方法一个栈帧（局部变量、操作数栈）</td><td>私有</td><td><code>StackOverflowError</code>（递归过深）</td></tr><tr><td><strong>程序计数器</strong></td><td>当前执行指令地址</td><td>私有</td><td>无</td></tr><tr><td><strong>直接内存</strong></td><td>NIO 的堆外内存</td><td>共享</td><td><code>OOM: Direct buffer memory</code></td></tr></tbody></table><p><strong>JDK 8 变化</strong>：永久代（PermGen）→ 元空间（Metaspace），从堆内移到了本地内存，不再有 PermGen OOM。</p><h2 id="垃圾回收-gc" tabindex="-1">垃圾回收（GC） <a class="header-anchor" href="#垃圾回收-gc" aria-label="Permalink to &quot;垃圾回收（GC）&quot;">​</a></h2><h3 id="判断对象可回收" tabindex="-1">判断对象可回收 <a class="header-anchor" href="#判断对象可回收" aria-label="Permalink to &quot;判断对象可回收&quot;">​</a></h3><ul><li><strong>引用计数法</strong>（早期）：循环引用问题，已弃用</li><li><strong>可达性分析</strong>（现用）：从 GC Roots 出发遍历，不可达即垃圾。GC Roots 包括：栈帧局部变量、静态变量、JNI 引用、活跃线程</li></ul><h3 id="回收算法" tabindex="-1">回收算法 <a class="header-anchor" href="#回收算法" aria-label="Permalink to &quot;回收算法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算法</th><th>思路</th><th>缺点</th></tr></thead><tbody><tr><td><strong>标记-清除</strong></td><td>标记垃圾后直接清除</td><td>内存碎片</td></tr><tr><td><strong>标记-复制</strong></td><td>存活对象复制到另一半区域</td><td>浪费一半空间；适合&quot;存活少&quot;（新生代）</td></tr><tr><td><strong>标记-整理</strong></td><td>存活对象移到一端，清掉其余</td><td>移动成本高；适合&quot;存活多&quot;（老年代）</td></tr></tbody></table><h3 id="分代收集" tabindex="-1">分代收集 <a class="header-anchor" href="#分代收集" aria-label="Permalink to &quot;分代收集&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新生代（复制算法，Minor GC 频繁）</span></span>
<span class="line"><span>├── Eden（新对象）</span></span>
<span class="line"><span>└── Survivor S0 / S1（幸存者，年龄 +1，15 岁进老年代）</span></span>
<span class="line"><span>老年代（标记-整理/标记-清除，Major GC）</span></span></code></pre></div><p><strong>为什么分代</strong>：绝大多数对象朝生夕灭（如方法里的临时对象），新生代用复制算法性价比最高。</p><h3 id="常见收集器-面试答-g1-即可" tabindex="-1">常见收集器（面试答 G1 即可） <a class="header-anchor" href="#常见收集器-面试答-g1-即可" aria-label="Permalink to &quot;常见收集器（面试答 G1 即可）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>收集器</th><th>特点</th></tr></thead><tbody><tr><td><strong>G1</strong>（JDK 9+ 默认）</td><td>分 Region 管理堆，可预测停顿时间（<code>-XX:MaxGCPauseMillis</code>），JDK 17 默认</td></tr><tr><td>ZGC</td><td>JDK 15+，超低停顿（毫秒级），适合超大堆</td></tr><tr><td>CMS</td><td>老牌并发收集器，已废弃（JDK 14+ 移除）</td></tr></tbody></table><p>G1 一句话：<strong>把堆分成多个 Region，优先回收垃圾最多的 Region</strong>（Garbage First 名字由来）。</p><h2 id="类加载机制" tabindex="-1">类加载机制 <a class="header-anchor" href="#类加载机制" aria-label="Permalink to &quot;类加载机制&quot;">​</a></h2><h3 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>加载 → 验证 → 准备 → 解析 → 初始化 → 使用 → 卸载</span></span></code></pre></div><ul><li><strong>加载</strong>：读 .class 文件生成 Class 对象</li><li><strong>验证</strong>：字节码安全校验</li><li><strong>准备</strong>：静态变量赋默认值（0 / null）</li><li><strong>解析</strong>：符号引用 → 直接引用</li><li><strong>初始化</strong>：执行静态代码块、静态变量赋真实值</li></ul><h3 id="双亲委派模型-必考" tabindex="-1">双亲委派模型（必考） <a class="header-anchor" href="#双亲委派模型-必考" aria-label="Permalink to &quot;双亲委派模型（必考）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>启动类加载器 Bootstrap（rt.jar，JDK 核心类）</span></span>
<span class="line"><span>  ↑ 委托</span></span>
<span class="line"><span>扩展类加载器 Platform（JDK 扩展类）</span></span>
<span class="line"><span>  ↑ 委托</span></span>
<span class="line"><span>应用类加载器 App（classpath 下的类）</span></span></code></pre></div><p><strong>流程</strong>：类加载请求 → 先问父加载器能不能加载 → 父都不行才自己加载。</p><p><strong>为什么这样设计</strong>：保证核心类安全——你的代码无法覆盖 <code>java.lang.String</code>，避免污染 JDK 核心类（核心类始终由 Bootstrap 加载）。</p><p><strong>打破双亲委派</strong>：SPI（JDBC 等）用线程上下文类加载器，Tomcat 也打破了（每个应用隔离）。</p><h2 id="jvm-调优与排查-面试基础" tabindex="-1">JVM 调优与排查（面试基础） <a class="header-anchor" href="#jvm-调优与排查-面试基础" aria-label="Permalink to &quot;JVM 调优与排查（面试基础）&quot;">​</a></h2><p>常用参数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-Xms256m -Xmx256m        # 堆初始/最大（生产建议相等，避免扩容抖动）</span></span>
<span class="line"><span>-Xss512k                 # 每个线程栈大小</span></span>
<span class="line"><span>-XX:MaxMetaspaceSize     # 元空间上限</span></span>
<span class="line"><span>-XX:+HeapDumpOnOutOfMemoryError   # OOM 时自动 dump</span></span></code></pre></div><p>排查命令（详见 <a href="/knowledge/service/troubleshooting.html">线上问题排查</a>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jps       # 查看 Java 进程</span></span>
<span class="line"><span>jstack    # 线程栈（查死锁、线程状态）</span></span>
<span class="line"><span>jmap      # 堆快照（查 OOM 对象）</span></span>
<span class="line"><span>jstat     # 查看 GC 频率与耗时</span></span></code></pre></div><h2 id="面试题速查" tabindex="-1">面试题速查 <a class="header-anchor" href="#面试题速查" aria-label="Permalink to &quot;面试题速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>一句话答案</th></tr></thead><tbody><tr><td>堆和栈的区别</td><td>堆存对象（共享）、栈存调用帧（私有）；堆要 GC、栈随方法退出自动释放</td></tr><tr><td>什么是 OOM</td><td>堆/元空间/直接内存耗尽的 <code>OutOfMemoryError</code></td></tr><tr><td>什么是 StackOverflow</td><td>栈深度超限，递归没出口</td></tr><tr><td>GC 判断对象死亡的算法</td><td>可达性分析（GC Roots）</td></tr><tr><td>新生代为什么用复制算法</td><td>存活少，复制成本低、无碎片</td></tr><tr><td>G1 和 CMS 区别</td><td>G1 分 Region、可预测停顿；CMS 已废弃</td></tr><tr><td>双亲委派是什么</td><td>子加载器先委托父加载器，保证核心类不被覆盖</td></tr><tr><td>什么时候触发 Full GC</td><td>老年代空间不足、元空间不足、System.gc()</td></tr></tbody></table><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/knowledge/service/java-concurrency.html">Java 并发编程</a> - JMM 与线程</li><li><a href="/knowledge/service/troubleshooting.html">线上问题排查</a> - jstack/jmap 实战</li><li><a href="/knowledge/service/java-basics.html">Java 入门（JS 开发者视角）</a> - 语言基础</li></ul>`,39)])])}const u=t(d,[["render",o]]);export{g as __pageData,u as default};
